/* Function  structure for function  `ZeeOrderID` */

/*!50003 DROP FUNCTION IF EXISTS `ZeeOrderID` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `ZeeOrderID`(_UserID varchar(20)) RETURNS varchar(150) CHARSET latin1
BEGIN
          DECLARE transactionID,_todayDate,_randomNo,_userCode VARCHAR(150) DEFAULT 'N';
	
	
	SELECT DATE_FORMAT(NOW(),'%y%m%d%i%s') INTO _todayDate;
	SELECT CAST(FLOOR(CONCAT('1',REPEAT('0','3')) + (RAND() * CONCAT('2',REPEAT('0','3'))))AS BINARY) INTO _randomNo;
	SELECT CONCAT('ZL',_UserID,_todayDate,_randomNo) INTO transactionID;
	RETURN transactionID;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_AdminLogin` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_AdminLogin` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_AdminLogin`(_userid varchar(30),_password varchar(30))
BEGIN
                if exists(select `UserMobile` from `emplogin` where `UserMobile`=_userid and `UserPass`=_password and UserStatus='Y') then
                    select `pk_emp_id`,`UserMobile`,`UserName`,`UserRole`,(case `UserStatus` when 'Y' then 'Active' when 'N' then 'Inactive' else 'ETC' end) as 'Status','Y' as 'id','Login Success' as 'desc' 
                     from `emplogin` where `UserMobile`=_userid AND `UserPass`=_password;
                 else
                     select 'N' AS 'id','Check User ID & Password' AS 'desc';
                  end if;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_changePass` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_changePass` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_changePass`(_userid varchar(20),_currentpass varchar(50),_newpass varchar(50))
BEGIN
              if exists(select `zl_UserID` from `zeeuser_login` where (`zl_UserID`=_userid or `zl_usrMobile`=_userid) and `zl_codedPass`=md5(_currentpass)) then
                update `zeeuser_login` set `zl_codedPass`=md5(_newpass) where (`zl_UserID`=_userid OR `zl_usrMobile`=_userid) AND `zl_codedPass`=MD5(_currentpass);
                select 'Y' as 'id', 'Password Changed Successfully' as 'desc';
              else
                SELECT 'N' AS 'id', 'User Not Exists' AS 'desc';
              end if;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_checkCart` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_checkCart` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_checkCart`(_userid varchar(20))
BEGIN
            IF EXISTS(SELECT `fk_userID` FROM `zeeorder_details` WHERE `zl_status`='C' AND `fk_userID`=_userid) THEN 
                   SELECT `zl_product_id` FROM `zeeorder_details` WHERE `zl_status`='C' AND `fk_userID`=_userid;
                  END IF;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_createUser` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_createUser` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_createUser`(_userid varchar(20),_username varchar(50),_shopname varchar(50),_usermobile varchar(20),_useremail varchar(100),
    _Shopaddress varchar(50),_pincode varchar(20),_city varchar(30),_state varchar(30),_panno varchar(30),_aadharno varchar(30))
BEGIN
              if not exists(select `zl_usrName` from `zeeuser_login` where `zl_usrMobile`=_usermobile) then
                  values(_userid,_username,_shopname,_usermobile,_useremail,md5(_usermobile),_Shopaddress,_pincode,_city,_state,'Y',now(),_usermobile,_panno,_aadharno);
                 select 'Y' as 'id','User Created' as 'desc';
                else
                 SELECT 'N' AS 'id','User Already Exists!' AS 'desc';
                 end if;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_DeleteCart` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_DeleteCart` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_DeleteCart`(_prodid varchar(20),_userid varchar(20))
BEGIN
               if exists(select `zl_productName` from `zeeorder_details` where `zl_product_id`=_prodid and `zl_status`='C' and `fk_userID`=_userid) then
                 DELETE FROM zeeorder_details WHERE `zl_product_id`=_prodid AND `zl_status`='C' AND `fk_userID`=_userid;
                 select 'Y' as 'id','Product Removed' as 'desc';
                 else
                 SELECT 'N' AS 'id','This Product is Not Exists in Cart' AS 'desc';
                end if;

	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_forgotPass` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_forgotPass` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_forgotPass`(_userID varchar(20),_password varchar(50))
BEGIN
              if exists(select `zl_UserID` from `zeeuser_login` where `pk_user_id`=_userID) then
                update `zeeuser_login` set `zl_codedPass`=md5(_password),`zl_passPlain`=_password where `pk_user_id`=_userID;
                select 'Y' as 'id','Password Send' as 'desc';
                else
                 SELECT 'N' AS 'id','User Not Exits' AS 'desc';
                end if;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_OrderList` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_OrderList` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_OrderList`(_userid varchar(20))
BEGIN
              if exists(select `fk_userID` from `zeeorder_track` where `fk_userID`=_userid) then 
                select 'Y' as 'id','List Found' as 'Result',`zl_orderID` as 'OrderID',`zl_orderDate` as 'DateOrder',
                (case `zl_orderStatus` when 'D' then 'Delivered' when 'P' then 'Pending For Billing' when 'B' then 'Billing Complete' when 'S' then 'Shipped' else 'Pending' end) as 'Status',
                zl_orderShipID as 'OrderShipID',`zl_billDate` as 'BillDate',`zl_shipDate` as 'ShipDate',`zl_totaloforder` as 'TotalAmount' 
                from `zeeorder_track` where `fk_userID`=_userid;
               else
                SELECT 'N' AS 'id','List Not Found' AS 'Result';
                end if;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_Productlist` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_Productlist` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_Productlist`()
BEGIN
              SELECT `pk_product_id`,`ItemCode`,`ItemName`,`FrgnName`,`OnHand`,`Available`,`MRP`,`F_1`,`F_2`,`F_3`,`F_4`,`F_5`,`prod_images` FROM `productlist`;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_productList_insert` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_productList_insert` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_productList_insert`(_ItemCode varchar(30),_ItemName VARCHAR(50),_FrgnName VARCHAR(50),_OnHand VARCHAR(20),_Available VARCHAR(20),_MRP VARCHAR(20),_F1 VARCHAR(20),_F2 VARCHAR(20),_F3 VARCHAR(20),_F4 VARCHAR(20),_F5 VARCHAR(20))
BEGIN
             if not exists(select `ItemCode` from `productlist` where `ItemCode`=_ItemCode) then
               values (_ItemCode,_ItemName,_FrgnName,_OnHand,_Available,_MRP,_F1,_F2,_F3,_F4,_F5);
               SELECT 'Y' AS 'id','Product List Inserted' AS 'desc';
             else
               update `productlist` set `OnHand`=_OnHand,`Available`=_Available,`MRP`=_MRP,`F_1`=_F1,`F_2`=_F2,`F_3`=_F3,`F_4`=_F4,`F_5`=_F5 
                where `ItemCode`=_ItemCode;
                Select 'Y' as 'id','Product List Updated' as 'desc';
             end if;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_updateProfile` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_updateProfile` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_updateProfile`(_userID varchar(10),_usrName varchar(50),_shopName varchar(50),_emailid varchar(50),_address varchar(50),_pincode varchar(20),_city varchar(50),_state varchar(50))
BEGIN
              if exists(select `zl_UserID` from `zeeuser_login` where `zl_status`='Y' and `pk_user_id`=_userID) then
                update `zeeuser_login` set `zl_usrName`=_usrName,`zl_shopName`=_shopName,`zl_usrEmail`=_emailid,`zl_address`=_address,
                  `zl_pincode`=_pincode,`zl_city`=_city,`zl_state`=_state where `zl_status`='Y' AND `pk_user_id`=_userID;
                 select 'Y' as 'id','Details Updated' as 'desc';
                 else
                 SELECT 'N' AS 'id','User Not Found OR Deactive' AS 'desc';
                 end if;
              
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ViewCart` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ViewCart` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ViewCart`(_userid varchar(20))
BEGIN
                if exists(select `fk_userID` from `zeeorder_details` where `zl_status`='C' and `fk_userID`=_userid) then 
                   select  'Y' AS 'id','Cart View' AS 'Result',`zl_productName` as 'ProductName',`zl_count` as 'Quantity',`zl_mrp` as 'MRP',`zl_totalAmnt` as 'TotalAmount',
                   `zl_indate` as 'Adddate' from `zeeorder_details`
                   where `zl_status`='C' AND `fk_userID`=_userid;
                 else
                    select 'N' as 'id','Cart Empty' as 'Result';
                  end if;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_zladdtoCart` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_zladdtoCart` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_zladdtoCart`(_userid VARCHAR(10),_productName VARCHAR(200),_count VARCHAR(30),_mrp VARCHAR(20),_proid VARCHAR(30))
BEGIN
          IF EXISTS(SELECT `zl_UserID` FROM `zeeuser_login` WHERE `pk_user_id`=_userid) THEN 
               IF NOT EXISTS(SELECT `zl_product_id` FROM `zeeorder_details` WHERE `zl_product_id`=_proid AND `fk_userID`=_userid) THEN
                 VALUES (_userid,_productName,_count,_mrp,'C',NOW(),(_count*_mrp),_proid);
                 SELECT 'Y' AS 'id','Product added to cart' AS 'Result';
               ELSE 
                 UPDATE `zeeorder_details` SET zl_count=_count+_count,zl_totalAmnt=(_count+_count*_mrp) WHERE zl_status='C' AND `zl_product_id`=_proid AND `fk_userID`=_userid;
                 SELECT 'Y' AS 'id','Cart Updated' AS 'Result';
                END IF;
              END IF;        
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_zlLogin_User` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_zlLogin_User` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_zlLogin_User`(_userid varchar(50),_password varchar(150))
BEGIN
              if exists(select `pk_user_id` from `zeeuser_login` where (`zl_UserID`=_userid or `zl_usrMobile`=_userid) and `zl_codedPass`=md5(_password) limit 1) then
                 select 'Y' as 'id','Success' as 'Result',`pk_user_id` as 'uid',`zl_UserID` as 'UsrID',`zl_usrName` as 'UsrName',`zl_shopName` as 'ShopName',
                 `zl_usrMobile` as 'Mobile',`zl_usrEmail` as 'Email',`zl_codedPass` as 'Passes',`zl_address` as 'Address',`zl_pincode` as 'Pincode',`zl_city` as 'City',
                 `zl_state` as 'State',(case `zl_status` when 'Y' then 'Active' when 'N' then 'Deactive' else 'ETC' end) as 'Status',`zl_indate` as 'Date',`zl_passPlain` as 'Pass',`zl_pancardNo` as 'PanNo',`zl_aadharNo` as 'AadharNo'
                 from `zeeuser_login` where (`zl_UserID`=_userid OR `zl_usrMobile`=_userid) AND `zl_codedPass`=MD5(_password) LIMIT 1;
                 else
                 select 'N' as 'id','Invalid Credentials. Please check your credentials again.' AS 'Result';
                 end if;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_zlOrderList` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_zlOrderList` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_zlOrderList`(_UserList varchar(50))
BEGIN
              if exists(select `fk_userID` from `zeeorder_details` where `zl_order_ID`=_UserList) then 
                  select `pk_orderDet_id` as ordid,`fk_userID` as uid,`zl_order_ID` as orderID,`zl_productName` as ProductName,`zl_count` as Counts,
                  `zl_mrp` as mrp,(CASE `zl_status` WHEN 'P' THEN 'Accept' WHEN 'R' THEN 'Cancel' WHEN 'N' THEN 'Remove' ELSE 'ETC' END) as 'Status',`zl_indate` as 'Date',
                  `zl_totalAmnt` as 'Tamount' from `zeeorder_details` where `zl_order_ID`=_UserList;
                  end if;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_zlOrderPlace` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_zlOrderPlace` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_zlOrderPlace`(_userid varchar(20))
BEGIN
         DECLARE _mrp DECIMAL(30,6) DEFAULT 0;
	DECLARE _orderID,_productname,_productID,_count VARCHAR(200);
        SELECT `ZeeOrderID`(_userid) INTO _orderID;
             IF EXISTS(SELECT `fk_userID` FROM `zeeorder_details` WHERE `zl_status`='C' AND `fk_userID`=_userid) THEN
             SELECT SUM(`zl_totalAmnt`) INTO _mrp FROM `zeeorder_details` WHERE `zl_status`='C' AND fk_userID=_userid;
             SELECT `zl_product_id`,`zl_count` INTO _productID,_count FROM `zeeorder_details` WHERE `zl_status`='C' AND fk_userID=_userid;
             
                UPDATE `zeeorder_details` SET `zl_status`='P',`zl_order_ID`=_orderID WHERE `fk_userID`=_userid;
                 SELECT 'Y' AS 'id','Order Placed Successfully!' AS 'Result';
                 UPDATE `productlist` SET `OnHand`=`OnHand`-_count WHERE `ItemCode`=_productID;
               ELSE
               SELECT 'N' AS 'id','Product not found in cart' AS 'Result';
               END IF;
	END */$$
DELIMITER ;

